/* Cinematic UPS Card v0.5.0 — visual editor, configurable cinematic effects */
class CinematicUpsCard extends HTMLElement {
 constructor(){super();this.attachShadow({mode:'open'});}
 setConfig(c){this._signature=null;if(!c.battery_entity)throw Error('battery_entity is required');this.c=c;this.draw();}
 set hass(h){this.h=h;this.draw();}
 getCardSize(){return 5;}
 getGridOptions(){return {columns:12,rows:6,min_columns:6,min_rows:4};}
 static getConfigElement(){return document.createElement('cinematic-ups-card-editor');}
 static getStubConfig(){return {type:'custom:cinematic-ups-card',battery_entity:'sensor.ups_battery_charge'};}
 draw(){
  if(!this.h||!this.c)return;
  const c=this.c,h=this.h;
  const signature=JSON.stringify([c,...Object.keys(c).filter(k=>k.endsWith('_entity')).map(k=>h.states[c[k]]),new Date().toDateString()]);
  if(signature===this._signature)return;
  this._signature=signature;
  const get=k=>c[k]&&h.states[c[k]]?h.states[c[k]].state:'—';
  const num=k=>{let v=get(k);return v==='—'||!Number.isFinite(Number(v))?null:Number(v)};
  const esc=v=>String(v??'').replace(/[&<>"']/g,ch=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[ch]));
  const battery=num('battery_entity'),pct=battery===null?0:Math.max(0,Math.min(100,battery)),status=get('status_entity');
  const low=/(^| )(LB|RB|FSD|ALARM)( |$)/.test(status)||battery!==null&&pct<=20;
  const onBattery=/(^| )OB( |$)/.test(status);
  const glow=low?'#ff5364':onBattery?'#ffb43d':/^#[0-9a-f]{6}$/i.test(c.accent_color||'')?c.accent_color:'#36ff48';
  const statusLabel=status==='—'||/unknown|unavailable/.test(status)?'לא זמין':low?'אזהרה · '+status:onBattery?'עבודה על סוללה':status==='OL'||/^online$/i.test(status)?'Online':status;
  const beeperLabel=({disabled:'כבוי (מושהה)',enabled:'פעיל',muted:'מושתק',off:'כבוי',on:'פעיל'})[get('beeper_status_entity')]||get('beeper_status_entity');
  const runtime=num('runtime_entity'),unit=h.states[c.runtime_entity]?.attributes?.unit_of_measurement;
  const sec=runtime===null?null:runtime*(unit==='min'?60:unit==='h'?3600:1);
  const clock=sec===null?'—':[Math.floor(sec/3600),Math.floor(sec%3600/60),Math.floor(sec%60)].map(x=>String(x).padStart(2,'0')).join(':');
  const age=c.battery_install_date&&/^\d{4}-\d{2}-\d{2}$/.test(c.battery_install_date)?Math.max(0,Math.floor((Date.now()-new Date(c.battery_install_date+'T00:00:00').getTime())/86400000)):null;
  const metric=(name,key,unit,icon)=>'<div class="metric"><div class="ico">'+icon+'</div><div class="ml">'+name+'</div><strong>'+esc(get(key))+' <small>'+unit+'</small></strong></div>';
  this.shadowRoot.innerHTML='<style>'+
  ':host{display:block}ha-card{--glow:'+glow+';color:#eaf8ff;overflow:hidden;border-radius:22px;border:1px solid #2b5873;background:radial-gradient(ellipse at 50% 48%,#113a50 0%,#071a2e 48%,#020912 100%);box-shadow:0 16px 42px #0009,inset 0 0 30px #008bff22}'+
  '.wrap{position:relative;padding:20px;direction:rtl;background:linear-gradient(90deg,#ff990009,transparent 35%,#00bfff0b)}.header{display:flex;direction:ltr;justify-content:space-between;gap:12px;align-items:flex-start}.brand{font-size:30px;font-weight:1000;font-style:italic;letter-spacing:-2px}.model{font-size:13px}.heading{text-align:right;direction:rtl}.heading h2{font-size:19px;margin:0}.heading .sub{font-size:12px;color:#c7d9e7}.status{display:inline-block;color:var(--glow);border:1px solid var(--glow);border-radius:20px;padding:4px 13px;margin-top:9px;background:#061b18;box-shadow:0 0 13px #00ff3a33}'+
  '.hero{height:270px;display:grid;grid-template-columns:32% 34% 34%;align-items:center;direction:ltr}.battery-stage{position:relative;height:250px;display:flex;align-items:center;justify-content:center}.battery{width:112px;height:180px;position:relative;z-index:2;filter:drop-shadow(0 0 15px var(--glow))}.battery:before{content:"";position:absolute;top:-10px;left:30px;width:52px;height:15px;background:linear-gradient(90deg,#15566a,#bffff7,#15566a);border-radius:8px 8px 2px 2px}.glass{position:absolute;inset:0;border:3px solid #88eaf5;border-radius:29px 29px 22px 22px;overflow:hidden;background:linear-gradient(90deg,#041827,#23727c66,#041827);box-shadow:inset 8px 0 15px #baffff44,inset -9px 0 13px #0009}.liquid{position:absolute;bottom:0;left:2px;right:2px;height:var(--level);background:linear-gradient(90deg,#087a26,var(--glow) 48%,#096a20);transition:height 1.3s ease;box-shadow:0 0 25px var(--glow)}.liquid:before{content:"";position:absolute;top:-8px;left:0;right:0;height:16px;border-radius:50%;background:#d2ffcf;box-shadow:0 0 13px var(--glow)}.shine{position:absolute;inset:0;background:linear-gradient(100deg,transparent 14%,#ffffff44 28%,transparent 43%,transparent 69%,#bfffff3d 80%,transparent 87%)}.particle{position:absolute;bottom:0;left:var(--x);width:5px;height:5px;border-radius:50%;background:white;animation:rise 3s linear infinite;animation-delay:var(--delay)}@keyframes rise{0%{opacity:0}20%{opacity:1}100%{opacity:0;transform:translateY(-160px)}}.percentage{position:absolute;top:110px;left:50%;transform:translateX(-50%);font-size:33px;font-weight:900;z-index:4;direction:ltr;text-shadow:0 0 15px #00ff4d}.bolt{position:absolute;top:40px;left:50%;transform:translateX(-50%);z-index:4;font-size:28px}.ring{position:absolute;bottom:20px;width:160px;height:27px;border:3px solid #00c9ff;border-radius:50%;transform:perspective(180px) rotateX(40deg);box-shadow:0 0 16px #009fff,0 0 20px #ff8a00;background:#09f4a022}'+
  '.ups-stage{height:235px;position:relative;display:flex;justify-content:center;align-items:center}.ups-stage .ring{bottom:15px;width:92%;border-color:#ff9d27}.ups-photo{position:relative;z-index:2;width:95%;max-width:230px;max-height:180px;object-fit:contain;filter:drop-shadow(0 12px 13px #000a) drop-shadow(0 0 13px #00aaff66)}.ups-fallback{font-size:70px}.runtime{text-align:center;border:1px solid #21baff;border-radius:12px;background:linear-gradient(110deg,#082b47,#06182e);padding:10px;box-shadow:0 0 16px #008cff33;margin-bottom:12px}.runtime span{display:block;font-size:12px;color:#b8dced}.runtime strong{font-size:27px;direction:ltr;display:block;text-shadow:0 0 12px #1abfff}'+
  '.metrics{display:grid;grid-template-columns:repeat(4,minmax(0,1fr));gap:8px}.metric{min-width:0;text-align:center;background:linear-gradient(145deg,#10314a,#081a2d);border:1px solid #33739b;border-radius:12px;padding:11px 4px}.ico{font-size:23px;color:#76dfff}.ml{font-size:11px;color:#cce1ed;min-height:27px}.metric strong{display:block;font-size:20px;white-space:nowrap;direction:ltr}.metric small{font-size:11px}.controls{margin-top:12px;display:flex;justify-content:space-between;align-items:center;gap:8px;background:#081c30;border:1px solid #2d5976;border-radius:12px;padding:11px;font-size:12px}.controls button{border:1px solid #4b88a6;border-radius:8px;background:#183b55;color:#fff;padding:8px 12px;font:inherit;cursor:pointer}.age{font-size:11px;color:#9fc6d8;margin-top:8px}'+
  '@media(max-width:450px){.wrap{padding:13px 9px}.brand{font-size:24px}.heading h2{font-size:15px}.hero{height:250px}.battery{transform:scale(.85)}.ups-photo{max-width:150px}.metric{padding:8px 2px}.metric strong{font-size:16px}.ml{font-size:10px}.ico{font-size:18px}}@media(prefers-reduced-motion:reduce){.particle{animation:none}.liquid{transition:none}}'+
  '.center-info{display:flex;flex-direction:column;align-items:center;justify-content:flex-start;height:250px;direction:rtl;text-align:center;padding:7px 3px;box-sizing:border-box}.center-title{font-size:clamp(13px,2.8vw,19px);font-weight:750}.center-sub{font-size:clamp(11px,2.2vw,14px);color:#c6dfec}.center-status{border:1px solid var(--glow);border-radius:24px;padding:5px 12px;background:#0a6b20;color:#fff;margin-top:10px;box-shadow:0 0 14px #00ff4555}.center-beeper{font-size:11px;margin-top:11px;color:#d1dce7}.center-info .runtime{margin-top:auto;width:100%;box-sizing:border-box}.ups-stage{height:250px}.ups-photo{max-height:190px}@media(max-width:450px){.center-info{height:230px}.center-info .runtime strong{font-size:19px}.center-info .runtime span{font-size:10px}.center-status{padding:4px 8px;font-size:12px}.ups-stage{height:230px}.ups-photo{max-height:150px}}'+'\n/* Reference composition: compact 3-column stage, left-to-right metrics. */\n:host{container-type:inline-size;font-family:Arial,Helvetica,sans-serif}\nha-card{display:block;border-radius:18px;background:#060d13;border-color:#304754;box-shadow:0 10px 28px #0008}\n.wrap{padding:5.2% 5% 1.2%;isolation:isolate;background:radial-gradient(ellipse at 100% 45%,#008be636,transparent 47%),radial-gradient(ellipse at 0% 48%,#fd8b1238,transparent 42%),linear-gradient(110deg,#201609 0%,#080d12 35%,#040b12 70%,#0b2635)}\n.wrap:before{content:"";position:absolute;z-index:-1;inset:0;background:linear-gradient(90deg,transparent 3%,#ff9b254d 4%,transparent 5%,transparent 94%,#42b9ff22 96%,transparent 97%);box-shadow:inset 0 0 35px #000a;pointer-events:none}\n.wrap:after{content:"";position:absolute;z-index:-1;inset:49% 0 20%;background:repeating-linear-gradient(0deg,transparent 0 22px,#45829618 23px 24px),linear-gradient(100deg,#be630b30,transparent 40%,#0486d82b);transform:perspective(160px) rotateX(29deg);pointer-events:none}\n.header{position:absolute;top:10%;left:6%;z-index:3;pointer-events:none}.header .heading{display:none}.brand{font-size:clamp(19px,5.4cqw,34px);line-height:.95;color:#fff;letter-spacing:-1.6px;text-shadow:0 2px 4px #000}.model{font-size:clamp(10px,2.7cqw,16px);margin:4px 0 0 7px}\n.hero{height:38cqw;min-height:146px;max-height:275px;grid-template-columns:33% 30% 37%;align-items:stretch;gap:0}\n.battery-stage{height:100%;align-items:flex-end;padding-bottom:3%;box-sizing:border-box}\n.battery{width:63%;height:61%;margin-bottom:5%;filter:drop-shadow(0 0 7px #2eff5350)}\n.battery:before{top:-7%;left:28%;width:44%;height:9%;border:1px solid #8fc6d7;background:linear-gradient(90deg,#091a22,#3b6472 30%,#07121d 73%,#81cada);border-radius:50% 50% 0 0;box-shadow:0 -2px 5px #00aaff44}\n.glass{inset:0;border:2px solid #78c4c6;border-radius:48% / 10%;background:linear-gradient(90deg,#00301c90,#09542122 40%,#000b 90%);box-shadow:inset 5px 0 8px #d9fffc55,inset -6px 0 9px #000a;overflow:hidden}\n.glass:after{content:"";position:absolute;inset:0;background:linear-gradient(90deg,transparent 9%,#cfffff48 13%,transparent 19%,transparent 77%,#d1ffff3d 82%,transparent 88%);border-radius:inherit}\n.cap{position:absolute;z-index:5;top:-1%;left:-5%;right:-5%;height:15%;border-radius:50% / 30%;border:1px solid #b8edff;background:linear-gradient(90deg,#120f08,#e8aa3e 6%,#241b0c 12%,#101e28 45%,#4f8394 80%,#a7efff 89%,#111f2b 96%);box-shadow:0 -2px 6px #08b8ff66,0 2px 4px #000}\n.liquid{left:5%;right:5%;bottom:3%;max-height:86%;border-radius:0 0 42% 42% / 0 0 8% 8%;background:linear-gradient(90deg,#065b18,var(--glow) 30%,var(--glow) 56%,#0a6419);box-shadow:0 0 18px var(--glow),inset 7px 0 13px #caff6540}\n.liquid:before{height:9px;top:-4px;background:var(--glow);box-shadow:0 0 9px var(--glow),inset 0 2px 3px #fff9}\n.bolt{top:25%;font-size:clamp(23px,6.5cqw,42px);line-height:1;color:white;text-shadow:0 0 8px #fff8}.percentage{top:auto;bottom:13%;font-size:clamp(23px,5.7cqw,36px);line-height:1;color:#fff;white-space:nowrap}\n.shine{pointer-events:none;z-index:3;border-radius:40% / 10%}\n.ring{bottom:1%;width:98%;height:12%;box-sizing:border-box;transform:none;border:2px solid #21befe;background:radial-gradient(ellipse,#101d1d 48%,#237551 52%,#020b11 58%,#bc8728 63%,#050a10 68%);box-shadow:0 4px 0 #080c0e,0 7px 0 #324248,0 8px 9px #000,0 0 13px #14b2fc55}\n.ring:after{content:"";position:absolute;inset:13% 6%;border:1px solid #f9aa31;border-radius:50%;box-shadow:0 0 6px #ffa52d}\n.ups-stage{height:100%;align-items:center;padding-bottom:4%;box-sizing:border-box}.ups-stage .ring{bottom:11%;width:100%;height:17%;border-color:#3bc6ff}.ups-photo{width:96%;max-width:none;max-height:89%;object-fit:contain;transform:translateY(-5%);filter:drop-shadow(0 8px 5px #000b) drop-shadow(0 0 4px #20b8ff55)}\n.center-info{height:100%;padding:5% 1% 10%;box-sizing:border-box;justify-content:flex-start}.center-title{font-size:clamp(12px,3cqw,20px);line-height:1.3;max-width:100%;overflow-wrap:anywhere}.center-sub{font-size:clamp(9px,2.5cqw,15px);line-height:1.4;max-width:100%}.center-status{font-size:clamp(10px,2.7cqw,17px);margin-top:5%;padding:3px 15%;border-radius:22px;background:linear-gradient(#1b941c,#07580d);white-space:nowrap;line-height:1.1}.center-beeper{font-size:clamp(8px,2.15cqw,13px);margin-top:8%;white-space:nowrap}.center-info .runtime{width:110%;margin:auto -5% 0;padding:6% 2%;border-radius:12px;background:linear-gradient(120deg,#050d13dd,#073355c9);box-shadow:inset 0 0 12px #00aaff33,0 0 10px #09b4ff22}.runtime span{font-size:clamp(8px,2cqw,12px);white-space:nowrap}.runtime strong{font-size:clamp(19px,4.8cqw,30px);line-height:1.2;font-variant-numeric:tabular-nums}\n.metrics{direction:ltr;grid-template-columns:repeat(4,minmax(0,1fr));gap:1.3%;position:relative;margin-top:1%}.metric{padding:4% 2%;border-radius:11px;background:linear-gradient(120deg,#10171ae8,#071523e6);border-color:#27516a;display:flex;flex-direction:column;align-items:center;gap:2px;box-shadow:inset 0 0 9px #55baff0a}.metric:first-child{border-color:#48734d}.ico{font-size:clamp(17px,3.7cqw,24px);line-height:1;color:#bceaff}.ml{order:3;min-height:0;font-size:clamp(8px,1.9cqw,12px);direction:rtl;line-height:1.3}.metric strong{font-size:clamp(16px,3.6cqw,23px);line-height:1.15}.metric small{font-size:.7em}\n.controls{margin-top:2%;padding:1% 3%;min-height:25px;border-radius:10px;background:linear-gradient(110deg,#15191fe6,#092335c9);font-size:clamp(10px,2.5cqw,15px);justify-content:center;gap:5%}.controls button{padding:3px 10px;min-width:40%;border-radius:8px;background:linear-gradient(#233a4b,#172532);font-size:clamp(10px,2.1cqw,13px)}.age{margin-top:1%;font-size:clamp(8px,1.7cqw,11px);text-align:center}.ups-fallback{font-size:clamp(35px,12cqw,80px)}\n@media(prefers-reduced-motion:reduce){.particle{animation:none}}\n'+'</style><ha-card><div class="wrap"><div class="header"><div><div class="brand">EATON</div><div class="model">5E 2200</div></div><div class="heading"><h2>'+esc(c.name||'3D Printers')+'</h2><div class="sub">'+esc(c.model||'Eaton 5E 2200')+'</div><div class="status">✓ '+esc(statusLabel)+'</div></div></div>'+
  '<div class="hero"><div class="battery-stage"><div class="ring"></div><div class="battery"><div class="cap"></div><div class="glass"><div class="liquid" style="--level:'+pct+'%"><i class="particle" style="--x:25%;--delay:0s"></i><i class="particle" style="--x:60%;--delay:1s"></i><i class="particle" style="--x:45%;--delay:2s"></i></div></div><div class="shine"></div><div class="bolt">ϟ</div><div class="percentage">'+(battery===null?'—':Math.round(pct)+'%')+'</div></div></div><div class="center-info"><div class="center-title">'+esc(c.name||'3D Printers')+'</div><div class="center-sub">'+esc(c.model||'Eaton 5E 2200')+'</div><div class="center-status">✓ '+esc(statusLabel)+'</div><div class="center-beeper">♧ מצב זמזם: '+esc(beeperLabel)+'</div><div class="runtime"><span>◷ זמן עבודה בסוללה</span><strong>'+esc(clock)+'</strong></div></div><div class="ups-stage"><div class="ring"></div>'+(c.image?'<img class="ups-photo" src="'+esc(c.image)+'" alt="UPS">':'<span class="ups-fallback">▣</span>')+'</div></div><div class="metrics">'+metric('עומס נוכחי','load_entity','%','◴')+metric('הספק מדומה','apparent_power_entity','VA','∿')+metric('מתח כניסה','voltage_entity','V','♧')+metric('הספק אמיתי','power_entity','W','ϟ')+'</div>'+'<div class="controls"><span>♬ זמזם אל פסק</span>'+(c.beeper_entity?'<button id="beeper">'+esc(beeperLabel)+' ▾</button>':'—')+'</div>'+(age===null?'':'<div class="age">מצברים הותקנו: '+esc(c.battery_install_date)+' · גיל '+age+' ימים</div>')+'</div></ha-card>';
  const button=this.shadowRoot.getElementById('beeper');
  if(button)button.addEventListener('click',()=>this.dispatchEvent(new CustomEvent('hass-more-info',{bubbles:true,composed:true,detail:{entityId:c.beeper_entity}})));
 }
}
if(!customElements.get('cinematic-ups-card'))customElements.define('cinematic-ups-card',CinematicUpsCard);
window.customCards=window.customCards||[];
if(!window.customCards.some(c=>c.type==='cinematic-ups-card'))window.customCards.push({type:'cinematic-ups-card',name:'Cinematic UPS Card',description:'Cinematic animated UPS monitor'});

class CinematicUpsCardEditor extends HTMLElement {
 constructor(){super();this.attachShadow({mode:'open'});this.config={};}
 set hass(h){this._hass=h;if(!this.shadowRoot.querySelector('.fields'))this.render();}
 setConfig(c){this.config={...c};this.render();}
 render(){
  if(!this._hass)return;
  const fields=[
   ['name','שם הכרטיס','text'],['model','דגם האל פסק','text'],
   ['status_entity','מצב UPS','entity'],['battery_entity','אחוז סוללה','entity'],
   ['runtime_entity','זמן גיבוי','entity'],['load_entity','עומס','entity'],
   ['power_entity','הספק אמיתי (W)','entity'],['apparent_power_entity','הספק מדומה (VA)','entity'],
   ['voltage_entity','מתח כניסה','entity'],['beeper_status_entity','מצב זמזם','entity'],
   ['beeper_entity','שליטה בזמזם','entity'],['image','נתיב תמונת UPS','text'],
   ['battery_install_date','תאריך החלפת מצברים','date'],['accent_color','צבע ניאון','color']
  ];
  const esc=x=>String(x??'').replace(/[&<>"']/g,z=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[z]));
  const options=Object.keys(this._hass.states).sort();
  this.shadowRoot.innerHTML='<style>:host{display:block;direction:rtl;color:var(--primary-text-color)}.fields{display:grid;grid-template-columns:repeat(auto-fit,minmax(210px,1fr));gap:12px}.field{display:flex;flex-direction:column;gap:5px;font-size:13px}input,select{box-sizing:border-box;width:100%;border:1px solid var(--divider-color,#777);border-radius:8px;padding:10px;background:var(--card-background-color,#fff);color:var(--primary-text-color,#111);font:inherit}input[type=color]{height:44px}h3{margin:10px 0 15px}</style><h3>הגדרות Cinematic UPS Card</h3><div class="fields">'+
  fields.map(([key,label,type])=>'<label class="field"><span>'+label+'</span>'+(type==='entity'?'<input list="entities" data-key="'+key+'" value="'+esc(this.config[key]||'')+'" placeholder="בחר או הקלד ישות">':'<input data-key="'+key+'" type="'+type+'" value="'+esc(this.config[key]||(type==='color'?'#36ff48':''))+'">')+'</label>').join('')+'</div><datalist id="entities">'+options.map(id=>'<option value="'+esc(id)+'"></option>').join('')+'</datalist>';
  this.shadowRoot.querySelectorAll('[data-key]').forEach(input=>input.addEventListener('change',()=>{
    const next={...this.config,[input.dataset.key]:input.value};
    if(!next[input.dataset.key])delete next[input.dataset.key];
    this.config=next;
    this.dispatchEvent(new CustomEvent('config-changed',{detail:{config:next},bubbles:true,composed:true}));
  }));
 }
}
if(!customElements.get('cinematic-ups-card-editor'))customElements.define('cinematic-ups-card-editor',CinematicUpsCardEditor);
